$(()=>{get_astral_guide()});var rout=_sajoURL_+"/wp-json/astral/guides";let currentPage=1;const perPage=9;function get_astral_guide(){$.ajax({method:"GET",url:rout,data:{page:currentPage,per_page:perPage}}).done(e=>{print_astral_guides(e),e.page>=e.max_pages?$(".see-more").hide():$(".see-more").show()})}function print_astral_guides(e){var a=e.astral_guide;console.log(a);var t=$("#astral-guides");if(a.length>0)for(item of a)t.append(`\n                <a href="${item.permalink}" class="the-guide">\n                    ${item.feature_image}\n                    <div class="text">\n                        <h3 class="guide-name">${item.guide_name}</h3>\n                        <hr>\n                        <p class="date">${item.the_date}</p>\n                    </div>\n                </a>\n            `);else t.html('<p class="there-are-no-guides">No tenemos contenido aun</p>')}$(".see-more").on("click",function(){currentPage++,get_astral_guide(!0)});